#!/usr/bin/env python3
"""Actual original Haskell/RAM expectations, never generated by Kotlin."""
import argparse,gzip,hashlib,importlib.util,json,random,re,subprocess,sys
from pathlib import Path
sys.dont_write_bytecode=True
ROOT=Path(__file__).resolve().parents[1];FOLDER=ROOT/'tools/curve25519-public-reference';TARGET=ROOT/'core/src/test/resources/crypto-curve25519-public/data.jsonl.gz'
def inputs():
 rows=[];rng=random.Random(2551906013)
 def add(group,op,**kw):rows.append(dict(group=group,request=dict(op=op,**kw)))
 for n in [0,1,15,16,31,32,33,63,64,65,255,256]:
  for op in ['secretKey','publicKey','dhSecret','decodePoint','decodeScalar']:add('constructor-exact-length-errors',op,bytes=[i%256 for i in range(n)])
 data=[[b]*32 for b in range(256)]+[list(rng.randbytes(32))for _ in range(100)]
 for i,b in enumerate(data):
  for op in ['secretKey','publicKey','dhSecret','debugShow','force','encodePoint','encodeScalar']:add('immutable-wrapper-all-byte-values',op,bytes=b)
  for prec in [-1,0,10,11,100]:
   for op in ['secretShow','publicShow','dhShow']:add('RAM-show-constructor-precedence',op,bytes=b,precedence=prec)
  other=data[(i+1)%len(data)]
  for op in ['secretEq','publicEq','dhEq']:
   add('byte-equality',op,bytes=b,other=b);add('byte-inequality',op,bytes=b,other=other)
 for b in data[:16]+data[-100:]:
  for op in ['generate','generateScalar','generateKeyPair','toPublic','scalarToPoint','pointRoundtrip']:add('RNG-one-request-clamp-copy-and-public-key',op,bytes=b)
  add('original-ECDH-commutes-family', 'commutes',bytes=b,other=data[(sum(b)+3)%len(data)])
 add('RNG-provider-exception','generateThrow');add('modern-size','modernSizes')
 weak=re.findall(r'vpHex = "([0-9a-f]+)"', (ROOT/'vendor/crypton-2.0.1/tests/ECCSpec.hs').read_text().split('vectorsWeakPoint =',1)[1].split('vpEncodedPoint ::',1)[0])[:7];assert len(weak)==7
 decode=[[],list(bytes.fromhex('22cd98c65fb50db3be0d6d359456c0cd3516952a6e7229ff672893944f703f10')),list(bytes.fromhex('23cd98c65fb50db3be0d6d359456c0cd3516952a6e7229ff672893944f703f10')),list(bytes.fromhex('0023cd98c65fb50db3be0d6d359456c0cd3516952a6e7229ff672893944f703f10'))]
 for b in decode:add('original-X25519-decode-vectors','decodePoint',bytes=b)
 points=weak+[(v).to_bytes(32,'little').hex()for v in [(1<<255)-19,(1<<255)-18,(1<<255)-1,1<<255,(1<<256)-1]]
 for i,p in enumerate(points):
  for b in data[:8]+data[-8:]:
   for op in ['dh','ecdhRaw','ecdh']:add('raw-zero-allowed-modern-contributory-and-noncanonical','%s'%op,bytes=b,point=list(bytes.fromhex(p)))
 for p in weak:add('original-X25519-weak-point','ecdh',bytes=list(rng.randbytes(32)),point=list(bytes.fromhex(p)))
 literal=re.findall(r'"((?:\\x[0-9a-f]{2})+)"',(ROOT/'vendor/crypton-2.0.1/tests/Curve25519Spec.hs').read_text());alice,ap,bob,bp,shared=[list(bytes.fromhex(s.replace('\\x','')))for s in literal]
 for name,op,b,p,expected in [('0','dh',bob,ap,shared),('1','dh',alice,bp,shared),('2','toPublic',alice,None,ap),('3','toPublic',bob,None,bp)]:
  r=dict(bytes=b,kat=name,katExpected=expected)
  if p is not None:r['point']=p
  add('original-Curve25519Spec-KAT',op,**r)
 return rows

def hashes():
 files=[]
 for package,archive in [('crypton-2.0.1','9e2fcd5c9326d85076cb48cee7fdd9add98384d9d9b79af0ccba0ae9d99c5914'),('ram-0.22.1','72474962349dd101b970cc46bcc06c799f7311d228e7b59f1a44f81427159f70')]:
  d=ROOT/'vendor'/package;m=json.loads((d/'SOURCE.json').read_text());assert m['sha256']==archive
  for p,h in m['files'].items():assert hashlib.sha256((d/p).read_bytes()).hexdigest()==h,p
  if package.startswith('ram'):files += [p for p in d.rglob('*')if p.is_file()]
  else:files += [d/p for p in ['SOURCE.json','Crypto/PubKey/Curve25519.hs','Crypto/ECC.hs','Crypto/Debug.hs','Crypto/Internal/ByteArray.hs','tests/Curve25519Spec.hs','tests/ECCSpec.hs','tests/Imports.hs','tests/Utils.hs','crypton.cabal']]
 spec=importlib.util.spec_from_file_location('extract',ROOT/'tools/extract-curve25519-public-reference.py');ex=importlib.util.module_from_spec(spec);spec.loader.exec_module(ex)
 for name,text in ex.sources().items():assert(FOLDER/name).read_text()==text
 files += [Path(__file__).resolve(),ROOT/'tools/extract-curve25519-public-reference.py',ROOT/'licenses/crypton-BSD-3-Clause.txt',ROOT/'licenses/ram-BSD-3-Clause.txt']+[p for p in FOLDER.glob('*')if p.is_file()]
 return{str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest()for p in sorted(set(files))}
def digest(rows):return hashlib.sha256(''.join(json.dumps(r,sort_keys=True,separators=(',',':'))for r in rows).encode()).hexdigest()
def suite(oracle,mode):
 p=subprocess.run([oracle,mode,'--seed','1729','--qc-max-success','100'],capture_output=True,text=True,check=True,timeout=240)
 expected=4 if mode=='--original' else 13
 assert re.search(r'\b'+str(expected)+r' examples, 0 failures',p.stdout),p.stdout
 return p.stdout
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--oracle');p.add_argument('--check-source',action='store_true');p.add_argument('--verify-oracle',action='store_true');args=p.parse_args()
 if not args.check_source:assert args.oracle,'--oracle required'
 if args.check_source or args.verify_oracle:
  with gzip.open(TARGET,'rt')as f:manifest=json.loads(next(f));rows=[json.loads(l)for l in f]
  assert manifest['sources']==hashes()and manifest['caseHash']==digest(rows)and manifest['cases']==len(rows)
  assert[r['request']for r in rows]==[r['request']for r in inputs()]
 else:
  raw=suite(args.oracle,'--original');modern=suite(args.oracle,'--modern');(FOLDER/'OriginalSuite.txt').write_text(raw+'\n'+modern);rows=inputs()
 if not args.check_source or args.verify_oracle:
  result=subprocess.run([args.oracle],input=''.join(json.dumps(r['request'],separators=(',',':'))+'\n'for r in rows),capture_output=True,text=True,check=True,timeout=240)
  values=[json.loads(l)for l in result.stdout.splitlines()];assert len(values)==len(rows)
  for row,expected in zip(rows,values):
   if'expected'in row:assert row['expected']==expected,row['request']
   else:row['expected']=expected
   if'katExpected'in row['request']:assert expected['bytes']==row['request']['katExpected']
  if args.verify_oracle:suite(args.oracle,'--original');suite(args.oracle,'--modern')
 if not(args.check_source or args.verify_oracle):
  manifest=dict(cases=len(rows),caseHash=digest(rows),sources=hashes(),originalExamples=4,modernPartition={'decodeVectors':4,'weakPoints':7,'propertyFamilies':2,'examples':13,'remainingFamilies':['X448','Edwards25519']},limits='Valid MonadRandom providers return exactly requested32bytes. Malformed provider length is outside source precondition and excluded (source may access invalid memory). Finite NFData/owned snapshots observed; JVM constant timing, physical erasure and GHC bottom/laziness equivalence not proven. Raw Donna bothprofiles verified separately; no actual32OS ABI claim.')
  TARGET.parent.mkdir(parents=True,exist_ok=True)
  with TARGET.open('wb')as raw:
   with gzip.GzipFile(filename='',mode='wb',fileobj=raw,mtime=0)as f:f.write(('\n'.join(json.dumps(r,separators=(',',':'))for r in[manifest]+rows)+'\n').encode())
 print('Verified'if args.check_source or args.verify_oracle else'Generated',len(rows),'original publicCurve25519 cases;',len(hashes()),'pins')
